246	// A conflicting submit against a waiting record leaves its content, status,
247	// reason, attempt count and retry schedule exactly as they were, including
248	// when only the proof height or the expiry changes.
249	func TestSubmitConflictWhileWaitingKeepsRecordAndSchedule(t *testing.T) {
250		q, _ := openTempQueue(t)
251		defer q.Close()
252		q.RegisterSource("chain-a")
253		q.UpsertHeader(Header{Chain: "chain-a", Height: 100, Root: "0x100", Trusted: true})
