255		env := Envelope{
256			Message:   Message{ID: "w", From: "chain-a", To: "chain-b", Nonce: 8, Payload: "world", ProofAt: 110},
257			ExpiresAt: 9_000_000_000_000,
258		}
259		q.Submit(env)
260		q.Advance(1_700_000_000_000)
261		before := statusOf(t, q, "w")
262		beforeQ, _ := q.Query("w")
263	
264		for _, mutate := range []func(Envelope) Envelope{
265			func(e Envelope) Envelope { e.Message.ProofAt = 111; return e },
266			func(e Envelope) Envelope { e.ExpiresAt = 9_000_000_000_001; return e },
267			func(e Envelope) Envelope { e.Message.Payload = "WORLD"; return e },
268			func(e Envelope) Envelope { e.Message.Nonce = 9; return e },
269			func(e Envelope) Envelope { e.Message.From = "chain-a2"; return e },
270			func(e Envelope) Envelope { e.Message.To = "chain-c"; return e },
271		} {
272			if _, err := q.Submit(mutate(env)); !errors.Is(err, ErrConflict) {
273				t.Fatalf("waiting content change must be ErrConflict: %v", err)
274			}
275			got := statusOf(t, q, "w")
276			if got.Status != before.Status || got.Reason != before.Reason ||
277				got.Attempts != before.Attempts || got.NextRetry != before.NextRetry ||
278				got.Msg != before.Msg {
279				t.Fatalf("waiting record changed on rejected submit:\nbefore=%+v\nafter =%+v", before, got)
280			}
281		}
282		if got, _ := q.Query("w"); got != beforeQ {
283			t.Fatalf("query view changed: %+v", got)
284		}
285		if len(q.order) != 1 {
286			t.Fatalf("conflict added a queue entry: %v", q.order)
287		}
288	}
