366	// Once a message is terminal, identical and differing content alike return
367	// ErrTerminal (never ErrConflict), for success as well as the other terminal
368	// statuses; the stored record stays queryable with its status and reason.
369	func TestSubmitTerminalIDAlwaysErrTerminal(t *testing.T) {
370		t.Run("success", func(t *testing.T) {
371			q, _ := openTempQueue(t)
372			defer q.Close()
373			q.RegisterSource("a")
374			q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true})
375			e := env("m", "a", "b", 1, 10, 0)
376			q.Submit(e)
377			q.Advance(1000)
378	
379			if _, err := q.Submit(e); !errors.Is(err, ErrTerminal) {
380				t.Fatalf("identical resubmit of a success: want ErrTerminal, got %v", err)
381			}
382			bad := e
383			bad.Message.ProofAt = 11
384			if _, err := q.Submit(bad); !errors.Is(err, ErrTerminal) {
385				t.Fatalf("different content on a success: want ErrTerminal, got %v", err)
386			}
387			got := statusOf(t, q, "m")
388			if got.Status != StatusSuccess || got.NextRetry != 0 {
389				t.Fatalf("success record changed: %+v", got)
390			}
