392			rep, err := q.Advance(2000)
393			if err != nil {
394				t.Fatal(err)
395			}
396			if len(rep.Results) != 0 {
397				t.Fatalf("terminal message reappeared on advance: %+v", rep.Results)
398			}
399		})
