401		t.Run("expired", func(t *testing.T) {
402			q, _ := openTempQueue(t)
403			defer q.Close()
404			q.RegisterSource("a")
405			e := env("m", "a", "b", 1, 1000, 2000)
406			q.Submit(e)
407			q.Advance(1000) // waiting
408			q.Advance(2000) // expired
409			if _, err := q.Submit(e); !errors.Is(err, ErrTerminal) {
410				t.Fatalf("identical resubmit of expired: %v", err)
411			}
412			bad := e
413			bad.Message.Payload = "x"
414			if _, err := q.Submit(bad); !errors.Is(err, ErrTerminal) {
415				t.Fatalf("different content on expired: want ErrTerminal, got %v", err)
416			}
417			if got := statusOf(t, q, "m"); got.Status != StatusExpired {
418				t.Fatalf("expired record changed: %+v", got)
419			}
420		})
