422		t.Run("unknown-source", func(t *testing.T) {
423			q, _ := openTempQueue(t)
424			defer q.Close()
425			e := env("m", "ghost", "b", 1, 10, 0)
426			q.Submit(e)
427			q.Advance(1000)
428			if _, err := q.Submit(e); !errors.Is(err, ErrTerminal) {
429				t.Fatalf("identical resubmit of unknown-source: %v", err)
430			}
431			bad := e
432			bad.Message.ProofAt = 11
433			if _, err := q.Submit(bad); !errors.Is(err, ErrTerminal) {
434				t.Fatalf("different content on unknown-source: want ErrTerminal, got %v", err)
435			}
436			if got := statusOf(t, q, "m"); got.Status != StatusUnknownSrc {
437				t.Fatalf("unknown-source record changed: %+v", got)
438			}
439		})
440	
441		t.Run("replay", func(t *testing.T) {
442			q, _ := openTempQueue(t)
443			defer q.Close()
444			q.RegisterSource("a")
445			q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true})
446			winner := env("win", "a", "b", 3, 10, 0)
447			loser := env("lose", "a", "b", 3, 10, 0)
448			q.Submit(winner)
449			q.Submit(loser)
450			q.Advance(1000)
451			if _, err := q.Submit(loser); !errors.Is(err, ErrTerminal) {
452				t.Fatalf("identical resubmit of replay record: %v", err)
453			}
454			bad := loser
455			bad.Message.Payload = "p-changed"
456			if _, err := q.Submit(bad); !errors.Is(err, ErrTerminal) {
457				t.Fatalf("different content on replay record: want ErrTerminal, got %v", err)
458			}
459			if got := statusOf(t, q, "lose"); got.Status != StatusReplay {
460				t.Fatalf("replay record changed: %+v", got)
461			}
462		})
